\begin{equation}\label{eq:MML_k}
			L_k
		\coloneqq
			\frac{
				\|\nabla f(x^k) - \nabla f(x^{k-1})\|
			}{
				\|x^k - x^{k-1}\|
			}
		\end{equation}

\begin{align}
				\Lk
			\coloneqq{} &
				\frac{
					\innprod{\nabla f(x^{k-1})-\nabla f(x^k)}{x^{k-1}-x^k}
				}{
					\|x^{k-1}-x^k\|^2
				}
			\shortintertext{and}
				\ck
			\coloneqq{} &
				\frac{
					\|\nabla f(x^{k-1})-\nabla f(x^k)\|^2
				}{
					\innprod{\nabla f(x^{k-1})-\nabla f(x^k)}{x^{k-1}-x^k}
				}
			\end{align}

		for a pair of points \(x^{k-1},x^k\in\R^n\).
		Noting that the denominator of \(\Lk\) or \(\ck\) is zero iff \(\nabla f(x^k)-\nabla f(x^{k-1})=0\) (the latter owing to the Baillon-Haddad theorem \cite[Cor. 10]{baillon1977quelques}; see \cref{lem:enlarged:ck} for the local version needed here), we stick to the convention \(\frac00=0\) so that both \(\Lk\) and \(\ck\) are (well-defined, positive) real numbers.
		Throughout, we shall also adhere to \(\frac10=\infty\).


\begin{equation}\label{eq:PG:gamk}
			\gamk*
		=
			\min\set{
				\gamk\sqrt{1+\tfrac{\gamk}{\gamma_{k-1}}},\,
				\frac{
					\gamk
				}{
					2\sqrt{\left[\gamk\Lk(\gamk\ck-1)\right]_+}
				}
			}
		\end{equation}

			The set of real and extended-real numbers are \(\R\coloneqq(-\infty,\infty)\) and \(\Rinf\coloneqq\R\cup\set\infty\), while the positive and strictly positive reals are \(\R_+\coloneqq[0,\infty)\) and \(\R_{++}\coloneqq(0,\infty)\).
			We use the notation \([x]_+ = \max\set{0, x}\).
			With \(\id\) we indicate the identity function defined on a suitable space.
			We denote by \(\innprod{{}\cdot{}}{{}\cdot{}}\) and \(\|{}\cdot{}\|\) the standard Euclidean inner product and the induced norm.


			The diameter of \(\mathcal D\) is \(\diam\mathcal D\coloneqq\sup\set{\|x-y\|}[x,y\in\mathcal D]\), while its indicator function is \(\indicator_{\mathcal D}\), namely \(\indicator_{\mathcal D}(x)=0\) if \(x\in \mathcal D\) and \(\infty\) otherwise.
			Given two sets \(\mathcal D,\mathcal D'\subseteq\R^n\), the notation \(\mathcal D+\mathcal D'\coloneqq\set{x+x'}[x\in\mathcal D,\ x'\in\mathcal D']\) indicates their Minkowski sum.


			The notation \(\cball{\bar x}{r}\coloneqq\set{x}[\|x-\bar x\|\leq r]\) indicates the closed ball centered at \(\bar x\) and with radius \(r\).
			The \DEF{domain} and \DEF{epigraph} of an extended-real-valued function \(\func{h}{\R^n}{\Rinf}\) are the sets
			\(
				\dom h
			\coloneqq
				\set{x\in\R^n}[
					h(x)<\infty
				]
			\)
			and
			\(
				\epi h
			\coloneqq
				\set{(x, c )\in\R^n\times\R}[
					h(x)\leq c
				]
			\).
			Function \(h\) is said to be \DEF{proper} if \(\dom h\neq\emptyset\), and \DEF{lower semicontinuous (lsc)} if \(\epi h\) is a closed subset of \(\R^{n+1}\).


			We say that a differentiable function \(\func{h}{\R^n}{\R}\) has \DEF{locally Lipschitz continuous gradient} if for every convex and compact set \(\V\subset\R^n\) there exists \(L_{h,\V}>0\) such that
			\(
				\|\nabla h(x)-\nabla h(x')\|\leq L_{h,\V}\|x-x'\|
			\)
			holds for all \(x,x'\in\mathcal\V\).\footnote{%
				By virtue of \cite[Thm. 9.2]{rockafellar2009variational}, this condition is equivalent to \DEF{strict continuity} of \(\nabla h\) at every point, in the sense of \cite[Def. 9.1]{rockafellar2009variational}.
			}


\begin{equation}\label{eq:PG}
			\minimize_{x\in\R^n}\; \varphi(x) \coloneqq f(x)+g(x).
		\end{equation}

\begin{assumption}[Requirements for the proximal gradient setting]\label{ass:PG}
			The following hold in problem \eqref{eq:PG}:
			\begin{enumeratass}
			\item \label{ass:f}%
				\(\func{f}{\R^n}{\R}\) is convex and has locally Lipschitz continuous gradient.
			\item
				\(\func{g}{\R^n}{\Rinf}\) is proper, lsc, and convex.
			\item
				A solution exists: \(\argmin\varphi\neq\emptyset\).
			\end{enumeratass}
		\end{assumption}

		In addition to the gradient of the differentiable term, the fundamental oracle of {\algnamefont PGM} is the \emph{proximal mapping} \cite[Def. 6.1]{beck2017first}
		defined as
		\[
			\prox_{\tau g}(x)
		\coloneqq
			\argmin_{w\in\R^n}
			\set{g(w) + \tfrac{1}{2\tau}\|w-x\|^2},
		\]
		where \(\tau>0\) is a given stepsize.
		In the convex setting the proximal map is single valued and in fact Lipschitz continuous.


\begin{algorithm}[t]
			\caption{Adaptive proximal gradient method (\protect\adaPG)}
			\label{alg:PG}
			\begin{algorithmic}[1]
			\itemsep=3pt
			\Require
				starting point \(x^{-1}\in\R^n\)
				~and~
				stepsizes \(\gamma_0\geq\gamma_{-1}>0\)
			\Initialize
				\(x^0=\FBk[0]{x^{-1}}\)
			\item[\algfont{Repeat for} \(k=0,1,\ldots\) until convergence]
			\State \label{state:PG:gamk}%
				With \(\Lk\) and \(\ck\) as in \eqref{eq:CL}, define the stepsize as
			\hfill{\gray\footnotesize\sf // \([r]_+\coloneqq\max\set{r,0}\)}
				\[
					\gamk*
				=
					\gamk\min\set{
						\sqrt{1+\tfrac{\gamk}{\gamma_{k-1}}},\,
						\frac{
							1
						}{
							2\sqrt{\left[\gamk\Lk(\gamk\ck-1)\right]_+}
						}
					}
				\]
			\State
				\(x^{k+1}=\FBk*{x^k}\)
			\end{algorithmic}
		\end{algorithm}

\[
				\Hk\coloneqq\Fwk{}.
			\]

\begin{equation}\label{eq:rhoP}
				\rhok\coloneqq\tfrac{\gamk}{\gamma_{k-1}}
			\quad\text{and}\quad
				P_k\coloneqq\varphi(x^k)-\min\varphi.
			\end{equation}

