\begin{proof}~
					\begin{proofitemize}
					\item \itemref{thm:PG:SD}~
						Expressed in terms of \(\U_k(x^\star)\), the inequality in \cref{thm:PG:descent} simplifies to the one in the statement. The update rule for \(\gamk\) implies that the coefficients indicated in the statement are greater than or equal to zero, and the claim follows.

					\item \itemref{thm:PG:gamk}~
						The proven inequality implies that \(\seq{\U_k(x_{}^{\star })}\) converges for any \(x^\star\in\argmin\varphi\).
						Taking into account the nonnegativity of the last two terms in the definition of \(\U_k(x^\star)\), it follows that \(\seq{x^k}\) is bounded.
						As such, \(\V\) and \(L_{f,\V}\) as in the statement exist.
							Observe that
							\begin{equation}\label{eq:relate:MM}
								\tfrac{\gamk}{2\sqrt{[\gamk\Lk(\gamk\ck-1)]_+}}
							=
								\tfrac12
								\sqrt{\tfrac{1}{\Lk\ck}\tfrac{\gamk\ck}{[\gamk\ck-1]_+}}
							\geq
								\tfrac{1}{2\sqrt{\Lk\ck}}
							=
								\tfrac{1}{2L_k},
							\end{equation}
							where the last identity owes to \cref{thm:PG:CL}, and therefore
							\begin{equation}\label{eq:MM}
								\gamk*
							\geq
								\min\set{\gamk\sqrt{1+\rhok},\tfrac{1}{2L_k}}
							\end{equation}
							holds for every \(k\).
												Suppose that \(\gamk\leq\nicefrac{1}{2L_{f,\V}}\) for \(k=0,\dots,K\).
							Because of \eqref{eq:MM} and \cref{thm:Lk<=Ck}, this implies that
							\(
								\gamk*
							=
								\gamk\sqrt{1+\rhok}
							\)
							for \(k=0,\dots,K-1\).
												Then, for these \(k\) one has that
							\(
								\rhok*^2
							=
								1+\rhok
							>
								1
							\),
							which inductively gives
							\(
								\rhok^2
							\geq
								2
							\)
							for all \(k=1,\dots,K\) (since \(\rho_0 \geq 1\)).
							We then have
							\begin{equation}\label{eq:PG:gam2k}
								\gamma_K^2
							=
								\rho_K^2\gamma_{K-1}^2
							\geq
								2\gamma_{K-1}^2
							\geq\dots\geq
								2^K\gamma_0^2, 							\end{equation}
							showing that in at most \(k_0\) iterations stepsize exceeds \(\nicefrac{1}{2L_{f,\V}}\).
							From this point, a trivial induction argument using \eqref{eq:MM} reveals that \(\gamk\geq\nicefrac{1}{2L_{f,\V}}\) for all \(k\geq k_0\).
					\item \itemref{thm:PG:x*}~
						We begin by observing that, as is apparent from its proof, assertion \itemref{thm:PG:SD} remains valid if the identity in \eqref{eq:PG:gamk} is replaced by an inequality ``\(\leq\)''.
						Either way, a telescoping argument yields that
						\begin{equation}\label{eq:gPto0}
							\gamk(1+\rhok-\rhok*^2)P_{k-1}\to0
						\quad\text{as}\quad
							k\to\infty.
						\end{equation}
						We proceed by intermediate claims.
						\begin{claims}[widest*=3]%
						\item \label{claim:infP}
							{\it \(\liminf_{k\to\infty}P_k=0\), and in particular \(\seq{x^k}\) admits a limit point \(x_\infty \in \argmin \varphi \).}

							Since \(\seq{x^k}\) is bounded and \(\varphi\) is lsc, it suffices to show that \(\liminf_{k\to\infty}P_k=0\).
							If \(\limsup_{k\to\infty}(1+\rhok-\rhok*^2)>0\), then \eqref{eq:gPto0} yields the claim, since \(\gamk\) is bounded away from zero.
							Alternatively, since \(1+\rhok-\rhok*^2\geq0\), necessarily \(1+\rhok-\rhok*^2\to0\), from which it easily follows that \(\liminf_{k\to\infty}\rhok>1\), and that therefore \(\gamk\to\infty\);
							in this case, because of the inequalities \(\gamk\left(1+\rhok\right)P_{k-1}\leq\U_k\leq\U_1\), this directly proves that \(P_k\to0\).

						\item\label{claim:thm:PG:optunique}%
							{\it \(x_\infty\) is the only limit point that belongs to \(\argmin\varphi\).}

							Suppose that \(x_\infty'\in\argmin\varphi\) is a limit point.
							Observe that
							\[
								\innprod{x^k}{x_\infty - x_\infty'}
							=
								\U_k(x_\infty') - \U_k(x_\infty) + \tfrac12\|x_\infty\|^2 - \tfrac12\|x_\infty'\|^2,
							\]
							and since \(\seq{\U_k(x^\star)}\) is convergent for all \(x^\star\in \argmin \varphi\), then so is \(\seq{\innprod{x^k}{x_\infty - x_\infty'}}\).
							Passing to the limit along the two converging subsequences thus yields
							\(
								\innprod{x_\infty}{x_\infty - x_\infty'}
							=
								\innprod{x_\infty'}{x_\infty - x_\infty'}
							\),
							which after rearranging results in \(\|x_\infty - x_\infty'\|^2=0\), establishing the claim.

						\item\label{claim:thm:PG:allopt}%
							{\it \(\seq{x^k}\) converges to a point in \(\argmin\varphi\).}

							Let \(x_\infty\) be the (unique) optimal limit point of \(\seq{x^k}\) as in \cref{claim:thm:PG:optunique}, and let
							\begin{equation}\label{eq:U}
								U\coloneqq\lim_{k\to\infty}\U_k(x_\infty),
							\end{equation}
							which exists since the sequence is monotonically decreasing by assertion \itemref{thm:PG:SD}.
							Because of the inequality \(\frac{1}{2}\|x^k-x_{\infty}\|^2\leq\U_k(x_{\infty})\), it suffices to show that \(U=0\).
							Observe that, for every \(k\),
							\begin{equation}\label{eq:rhomax}
								\rhok\leq\rho_{\rm max}
							\quad\text{where}\quad
							 	\rho_{\rm max}
							 \coloneqq
								\max\set{\tfrac{\gamma_0}{\gamma_{-1}}, \tfrac12(1+\sqrt{5})}
							>
								1,
							\end{equation}
							as it can be verified by induction.
							We consider two mutually exclusive scenarios.
							\begin{proofitemize}[leftmargin=*]
							\item
								Suppose that \(\seq{\gamk}\) is bounded, and consider a subsequence \(\seq{x^k}[k\in K]\) such that \(\lim_{K\ni k\to\infty}P_k=0\), which exists and converges to \(x_{\infty}\) by virtue of the previous claims.
								Extract \(K'\subseteq K\) such that \(\seq{\gamk*}[k\in K']\to\gamma\) for some \(\gamma>0\).
								Then, \(x^{k+1}=\prox_{\gamk*g}(x^k-\gamk*\nabla f(x^k))\to\prox_{\gamma g}(x_\infty-\gamma\nabla f(x_\infty))=x_\infty\) as \(K'\ni k\to\infty\) as well.
								This yields the sought identity
								\begin{align*}
									U
								={} &
									\lim_{k\to\infty}\U_k(x_{\infty})
								=
									\lim_{K'\ni k\to\infty}\U_{k+1}(x_{\infty})
								\\
								={} &
									\lim_{K'\ni k\to\infty}\left(
										\tfrac{1}2\|x^{k+1}-x_{\infty}\|^2
										+
										\tfrac{1}2\|x^{k+1}-x^k\|^2
										+
										\gamk*\left(1+\rhok*\right)P_k
									\right)
								\\
								={} &
									0,
								\end{align*}
								where the vanishing of the last term owes to boundedness of \(\seq{\gamk}\) and \(\seq{\rhok}\).

							\item
								Suppose instead that \(\seq{\gamk}\) is unbounded, and let \(\seq{\gamk}[k\in K']\) be an arbitrary subsequence such that \(\gamk\to\infty\) as \(K'\ni k\to\infty\).
								From the inequality
								\(
									\gamk P_{k-1} \leq \U_k(x_{\infty}) \leq \U_1(x_\infty) < \infty
								\),
								we conclude that
								\begin{equation}\label{eq:Pk:xk-}
									P_{k-1}\to0
								~\text{ and }~
									x^{k-1}\to x_\infty
								\text{ as }
									K'\ni k\to\infty
								\end{equation}
								(recall that \(\varphi\) is lsc, \(\seq{x^k}\) is bounded, and \(x_\infty\) is the \emph{unique} optimal limit point).
								Then, since by \eqref{eq:rhomax} \(\gamma_{k-1}\geq\nicefrac{\gamk}{\rho_{\rm max}}\to\infty\) as \(K'\ni k\to\infty\), by the same argument also \(x^{k-2}\to x_\infty\) as \(K'\ni k\to\infty\).
								With \(U\) as in \eqref{eq:U}, we thus have
								\begin{equation}\label{eq:U:gam:unbounded}
										U
								=
									\lim_{k\to\infty}\U_k(x_\infty)
								=
									\lim_{K'\ni k\to\infty}\U_{k-1}(x_\infty)
								=
									\lim_{K'\ni k\to\infty}\gamma_{k-1}(1+\rho_{k-1})P_{k-2}
								\end{equation}
								holding for \emph{any} set of indices \(K'\subseteq\N\) along which the stepsizes are divergent.

								We now construct a specific subsequence \(K\coloneqq\set{k_0,k_1,\dots}\) as follows: start with \(k_0=1\), and for \(i\geq0\) let
								\begin{equation}\label{eq:ki+}
									k_{i+1}=\min\set{k\geq k_i}[\gamk \geq \rho_{\rm max}\gamma_{k_i}].
								\end{equation}
								Then, \(\seq{\gamma_{k_i}}[i\in\N]\to\infty\), which as argued after \eqref{eq:Pk:xk-} implies that both \(\seq{x^{k_i-1}}[i\in\N]\) and \(\seq{x^{k_i-2}}[i\in\N]\) converge to \(x_\infty\).
								Observe that \(\rho_{k_i}>1\) holds for all \(i\in\N\) by minimality of \(k_i\).
								Notice further that
								\begin{equation}\label{eq:k-1}
									\rho_{k_i-1}\geq\rho_{\rm max}^{-1}
								\quad
									\forall i\in\N.
								\end{equation}
								To see why, suppose on the contrary that
								\(
									\rho_{k_i-1}<\rho_{\rm max}^{-1}
								\);
								then in particular \(\rho_{k_i-1}<1\), thereby ensuring by the previous observation that \(k_i-1\notin K\), and thus \(k_{i-1}\leq k_i-2\).
								This leads to the contradiction
								\[
									\rho_{\rm max}
									\gamma_{k_{i-1}}
								\overrel[\leq]{\eqref{eq:ki+}}
									\gamma_{k_i}
								\overrel[\leq]{\eqref{eq:rhomax}}
									\rho_{\rm max}
									\gamma_{k_i-1}
								=
									\rho_{\rm max}
									\rho_{k_i-1}
									\gamma_{k_i-2}
								<
									\gamma_{k_i-2}
								<
									\rho_{\rm max}
									\gamma_{k_{i-1}},
								\]
								where the last inequality follows either in case \(k_i-2=k_{i-1}\) (since \(\rho_{\rm max}>1\)) or when \(k_{i-1}<k_i-2<k_i\) (from minimality in the definition of \(k_i\)).
								This shows \eqref{eq:k-1}.

								Next, by the stepsize update at \cref{state:PG:gamk},
								\begin{align*}
									\tfrac{1}{\rho_{\rm max}}\gamma_{k_i-2}L_{k_i-2}
								\overrel[\leq]{\eqref{eq:k-1}}
									\gamma_{k_i-1}L_{k_i-2}
								\leq{} &
									\frac{\gamma_{k_i-2}L_{k_i-2}}{2\sqrt{\left[\gamma_{k_i-2}^2\ell_{k_i-2}c_{k_i-2}-\gamma_{k_i-2}\ell_{k_i-2}\right]_+}}
								\\
								\leq{} &
									\frac{\gamma_{k_i-2}L_{k_i-2}}{2\sqrt{\left[\gamma_{k_i-2}^2L_{k_i-2}^2-\gamma_{k_i-2}L_{k_i-2}\right]_+}}
								\\
								={} &
									\frac{1}{2\sqrt{\left[1-\frac{1}{\gamma_{k_i-2}L_{k_i-2}}\right]_+}},
								\end{align*}
								where the third inequality uses the fact that \(L_{k_i-2}^2 = \ell_{k_i-2}c_{k_i-2}\), and \(\ell_{k_i-2}\leq L_{k_i-2}\) by \cref{thm:PG:cLl}.
								This implies that \(\seq{\gamma_{k_i-2}L_{k_i-2}}[i\in\N]\) must be bounded.
								The subgradient characterization in \eqref{eq:PG:vk} and the Cauchy-Schwarz inequality then yield
								\begin{align*}
									\gamma_{k_i-1} P_{k_i-2}
								\leq{} &
									\rho_{k_i-1}
									\innprod{x^{k_i-2}-x_{\infty}}{
										x^{k_i-2}-x^{k_i-3}
										-
										\gamma_{k_i-2}(\nabla f(x^{k_i-2})-\nabla f(x^{k_i-3}))
									}
								\\
								\leq{} &
									\rho_{\rm max}
									\underbracket[0.5pt]{
										(1+\gamma_{k_i-2}L_{k_i-2})
									}_{\text{bounded}}
									\,
									\underbracket[0.5pt]{
										\|x^{k_i-2}-x_{\infty}\|
										\|x^{k_i-2}-x^{k_i-3}\|
									}_{\to0}
								\to
									0
								\quad
									\text{as }i\to\infty.
