						f(z)
					\leq
						f(y)
						+
						\innprod{\nabla f(y)}{z-y}
						+
						\tfrac{L_{f,\overline\V}}{2}\|z-y\|^{2}
					\quad
						\forall z \in \overline\V.
					\end{equation}
					Let \(l_x(y) \coloneqq f(y) - f(x) - \innprod{\nabla f(x)}{y-x}\), and note that \(l_x\) is a convex function with \(\nabla l_x(y)=\nabla f(y)-\nabla f(x)\).
					For any \(z \in \overline\V\), we have
