						l_x(z)
					={} &
						f(z) - f(x) - \innprod{\nabla f(x)}{z-x}
					\\
					\overrel[\leq]{\eqref{eq:holder_ineq}}{} &
						f(y)
						+
						\innprod{\nabla f(y)}{z-y}
						+
						\tfrac{L_{f,\overline\V}}{2}\|z-y\|^{2}
						-
						f(x)
						-
						\innprod{\nabla f(x)}{z-x}
					\\
					={} &
						f(y) - f(x) - \innprod{\nabla f(x)}{y-x}
						+
						\innprod{\nabla f(y) - \nabla f(x)}{z-y}
						+
						\tfrac{L_{f,\overline\V}}{2}\|z-y\|^{2}
					\\
					={} &
						l_x(y)
						+
						\innprod{\nabla l_x(y)}{z-y}
						+
						\tfrac{L_{f,\overline\V}}{2}\|z-y\|^{2}.
					\end{align*}
