					\begin{qedalign*}
						0
					=
						\min l_x
					=
						l_x(x)
					\leq{} &
						l_x\Bigl(
							y - \tfrac{\|\nabla l_x(y)\|}{L_{f,\overline\V}}v
						\Bigr)
					\\
					\overrel[\leq]{\eqref{eq:holder_ineq}}{} &
						l_x(y)
						-
						\tfrac{\|\nabla l_x(y)\|}{L_{f,\overline\V}}
						\innprod{\nabla l_x(y)}{v}
						+
						\tfrac{L_{f,\overline\V}}{2}
						\tfrac{1}{L_{f,\overline\V}^{2}}
						\|\nabla l_x(y)\|^{2}
					\\
					={} &
						f(y) - f(x) - \innprod{\nabla f(x)}{y-x}
						-
						\tfrac{1}{2L_{f,\overline\V}}
						\|\nabla f(x) - \nabla f(y)\|^{2}.
					\end{qedalign*}
				\end{proof}
