			\sum_{k=1}^K\gamk
			+
			\sum_{k=1}^K(\gamk\rhok-\gamk*\rhok*)
		}
	\\
	\numberthis\label{eq:O(1k)}
	={} &
		\frac{\mathcal U_1}{
			\gamma_1\rho_1+\sum_{k=1}^{K+1}\gamk
		}
	\leq
		\frac{\mathcal U_1}{
			(K+1)\gamma_{\rm min}
		},
	\end{align*}
	where \(\gamma_{\rm min}\coloneqq\min\set{\gamma_0,\frac{1}{2L_{f,\mathcal V}}}\) is a lower bound on the stepsize, as demonstrated in the proof of assertion \itemref{thm:PG:gamk}.
	\qedhere
\end{proofitemize}
